package org.apache.commons.math.stat;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.text.NumberFormat;
import java.util.*;
import java.util.Comparator;
import java.util.Iterator;
import java.util.TreeMap;
import org.apache.commons.math.MathRuntimeException;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.math.stat.Frequency#getPct(Object)
 */
public class Frequency_getPct_TriageGen2Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }

    @Test
    public void testGetPctWithInteger() {
        frequency.addValue(1);
        frequency.addValue(1);
        frequency.addValue(2);
        frequency.addValue(3);

        // Total count = 4. Count of 1 is 2. Pct = 2/4 = 0.5
        // Note: getPct(Object) calls getCumPct(Comparable), 
        // but in Apache Commons Math, for single values, 
        // the behavior depends on the internal implementation of getCumPct.
        // We test the Object signature specifically.
        double result = frequency.getPct(Integer.valueOf(1));
        Assert.assertEquals(0.5, result, 1e-9);
    }














}

