public class Frequency_getPct_TriageGen2Test {

    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }











    @Test(expected = ClassCastException.class)
    public void testGetPctWithNonComparable() {
        // Create a non-comparable object
        class NonComparable {
            @Override
            public String toString() { return "non-comparable"; }
        }

        frequency.addValue(1);
        // This should trigger ClassCastException when casting Object to Comparable<?>
        frequency.getPct(new NonComparable());
    }




}

