    private Frequency frequency;

    @Before
    public void setUp() {
        frequency = new Frequency();
    }













    @Test
    public void testGetPctEmptyFrequency() {
        // Total count = 0. Division by zero in math usually results in NaN or 0.0 depending on implementation
        // In Commons Math, it returns 0.0 or NaN.
        double result = frequency.getPct(1);
        Assert.assertTrue(Double.isNaN(result) || result == 0.0);
    }


}

